//! Prepared-only ABI6 same-Store diagnostic; source packet, execution pending.
mod wasmtime_config;
mod wasmtime_policy;

use lila_aot_wasm::{
    build_runtime_artifact, emit_with_intl_profile_and_runtime_inputs,
    runtime_artifact_with_inputs, GcHostField, GcSnapshotField as F, PromiseRejectionPolicy,
    RuntimeArtifact, RuntimeArtifactCache, RuntimeArtifactCacheKey, RuntimeArtifactInputs,
    WasmArtifact, WasmRuntimeValueTag as Tag, RUNTIME_IMPORT_NAMESPACE,
};
use lila_ir::CompletionKindIr as Kind;
use std::sync::Arc;
use wasmtime::{
    ArrayRef, ArrayRefPre, AsContextMut, Caller, Engine, Error, ExternType, Func,
    GcHeapOutOfMemory, Instance, Linker, Memory, Module, Result, Rooted, SharedMemory, Store,
    StoreLimits, StoreLimitsBuilder, StructRef, StructRefPre, StructType, Val,
    WasmBacktraceDetails,
};

const P1: &str = r#"
(function receive(candidate) {
    "use strict";
    if (candidate === undefined) { print("compile-now"); return 17; }
    if (candidate === 0) { return Function("return 17;")(); }
    return candidate(40);
});
"#;
const P2: &str = r#"(function second(x) { "use strict"; return x + 2; });"#;
const P2_CONFLICT: &str = r#"
if (false) { Function("return 23;"); }
(function second(x) { "use strict"; return x + 2; });
"#;

// This binds the new raw package to the candidate compiler source manifests.
// It is a diagnostic source identity, never an old embedded-R admission token.
const SOURCE_IDENTITY: [u8; 32] = include!("source_identity.rs");

// The public raw builder ran first. Reject package-admission fallback rather
// than silently emitting a second R or consulting an ordinary runtime cache.
struct FreshPackageOnly;
impl RuntimeArtifactCache for FreshPackageOnly {
    fn compiler_identity(&self) -> &[u8; 32] {
        panic!("fresh ABI6 package rejected; no R fallback allowed")
    }
    fn load(&self, _: RuntimeArtifactCacheKey) -> Option<Vec<u8>> {
        unreachable!()
    }
    fn store(&self, _: RuntimeArtifactCacheKey, _: Vec<u8>) -> bool {
        unreachable!()
    }
    fn remove(&self, _: RuntimeArtifactCacheKey) {
        unreachable!()
    }
}
static FRESH_PACKAGE_ONLY: FreshPackageOnly = FreshPackageOnly;

struct FreshRuntime {
    runtime: Arc<RuntimeArtifact>,
    package: Vec<u8>,
}
impl FreshRuntime {
    fn build() -> Result<Self> {
        let selection =
            lila_intl::IntlDataSelection::new(lila_intl::IntlCompilationProfile::Minimal);
        let built = build_runtime_artifact(&selection, &SOURCE_IDENTITY)?;
        wasmparser::Validator::new_with_features(wasmparser::WasmFeatures::all())
            .validate_all(built.wasm())?;
        let runtime = runtime_artifact_with_inputs(
            &selection,
            RuntimeArtifactInputs::new(Some(&FRESH_PACKAGE_ONLY))
                .with_build_package(built.package_bytes(), &SOURCE_IDENTITY),
        )?;
        require(
            runtime.key() == built.key() && runtime.bytes() == built.wasm(),
            "fresh raw ABI6 R/package round-trip changed physical runtime",
        )?;
        println!("fresh-R-validated bytes={}", built.wasm().len());
        Ok(Self {
            runtime,
            package: built.package_bytes().to_vec(),
        })
    }
}

#[derive(Clone, Copy, Debug)]
enum EntryOrder {
    P1First,
    P2First,
}
#[derive(Clone, Copy, Debug)]
struct Case {
    conflict: bool,
    order: EntryOrder,
}

struct State {
    limits: StoreLimits,
    monotonic_origin: std::time::Instant,
    linker: Option<Linker<State>>,
    fresh: Arc<FreshRuntime>,
    memory: Option<Memory>,
    receive: Option<Rooted<StructRef>>,
    second: Option<Rooted<StructRef>>,
    call: Option<Func>,
    case: Case,
    entered: bool,
    transported: bool,
    native_compile_attempts: u32,
}

fn require(ok: bool, message: &str) -> Result<()> {
    if ok {
        Ok(())
    } else {
        Err(Error::msg(message.to_owned()))
    }
}

fn emit(
    source: &str,
    expected_prepared: Option<&str>,
    fresh: &FreshRuntime,
) -> Result<WasmArtifact> {
    let parsed = lila_front::parse(source, lila_front::ParseOptions::script())?;
    let program = lila_ir::lower(&parsed);
    let script = program
        .script
        .as_ref()
        .ok_or_else(|| Error::msg("fixture has no Script IR"))?;
    if let Some(body) = expected_prepared {
        require(
            script.prepared_dynamic_functions.iter().any(|entry| {
                entry.kind == lila_ir::DynamicFunctionKind::Ordinary
                    && entry.arguments.len() == 1
                    && entry.arguments[0] == body
                    && matches!(
                        &entry.outcome,
                        lila_ir::PreparedDynamicFunctionOutcome::Compiled { .. }
                    )
            }),
            "fixture did not lower its exact compiled prepared Function body",
        )?;
    } else {
        require(
            script.prepared_dynamic_functions.is_empty(),
            "transport P2 unexpectedly acquired a prepared Function catalogue",
        )?;
    }
    let artifact = emit_with_intl_profile_and_runtime_inputs(
        &program,
        PromiseRejectionPolicy::FailRun,
        &lila_intl::IntlCompilationProfile::Minimal,
        RuntimeArtifactInputs::new(Some(&FRESH_PACKAGE_ONLY))
            .with_build_package(&fresh.package, &SOURCE_IDENTITY),
    )?;
    let runtime = artifact
        .runtime()
        .ok_or_else(|| Error::msg("fixture P is not linked"))?;
    require(
        Arc::ptr_eq(runtime, &fresh.runtime)
            && runtime.key() == fresh.runtime.key()
            && runtime.bytes() == fresh.runtime.bytes(),
        "fixture selected another actual R",
    )?;
    Ok(artifact)
}

fn validate_and_compile(engine: &Engine, bytes: &[u8]) -> Result<Module> {
    wasmparser::Validator::new_with_features(wasmparser::WasmFeatures::all())
        .validate_all(bytes)?;
    Module::validate(engine, bytes)?;
    Ok(Module::new(engine, bytes)?)
}

// Same declaration/name lookup already used by runtime_regexp_compiler_tests.
fn helper_export(bytes: &[u8], helper: &str) -> Result<String> {
    for payload in wasmparser::Parser::new(0).parse_all(bytes) {
        let wasmparser::Payload::CustomSection(section) = payload? else {
            continue;
        };
        let wasmparser::KnownCustom::Name(names) = section.as_known() else {
            continue;
        };
        for subsection in names {
            if let wasmparser::Name::Function(names) = subsection? {
                for entry in names {
                    let entry = entry?;
                    if entry.name == helper {
                        return Ok(format!("f{}", entry.index));
                    }
                }
            }
        }
    }
    Err(Error::msg(format!("no physical {helper} export")))
}

fn results<S: AsContextMut<Data = State>>(cx: &mut S, f: Func, args: &[Val]) -> Result<Vec<Val>> {
    let mut output = f
        .ty(cx.as_context())
        .results()
        .map(|ty| Val::default_for_ty(&ty).ok_or_else(|| Error::msg("non-defaultable completion")))
        .collect::<Result<Vec<_>>>()?;
    require(output.len() == 5, "expected actual five-slot Completion")?;
    f.call(&mut *cx, args, &mut output)?;
    Ok(output)
}

fn structure<S: AsContextMut<Data = State>>(cx: &S, value: Val) -> Result<Rooted<StructRef>> {
    let Val::AnyRef(Some(value)) = value else {
        return Err(Error::msg("expected rooted GC reference"));
    };
    value
        .as_struct(cx.as_context())?
        .ok_or_else(|| Error::msg("expected actual GC struct"))
}

fn field<S: AsContextMut<Data = State>>(cx: &mut S, value: Rooted<StructRef>, f: F) -> Result<Val> {
    value.field(&mut *cx, f.index() as usize)
}

fn main_function<S: AsContextMut<Data = State>>(
    cx: &mut S,
    instance: Instance,
) -> Result<Rooted<StructRef>> {
    let main = instance
        .get_func(&mut *cx, "main")
        .ok_or_else(|| Error::msg("missing main"))?;
    let value = results(cx, main, &[])?;
    let kind =
        lila_aot_wasm::check_gc_main_completion(value[3].unwrap_i32(), value[4].unwrap_i32())
            .map_err(Error::msg)?;
    require(
        kind == Kind::Normal && value[0].unwrap_i32() == Tag::Function.tag(),
        &format!("main did not return FunctionObject: {value:?}"),
    )?;
    structure(cx, value[2])
}

// Use the existing R ProxyCall helper, not a new callable wrapper or a copied
// ordinary-body ABI. All arrays/StoredValues derive from its actual
// canonical signature and declaration-owned public field witnesses.
fn invoke<S: AsContextMut<Data = State>>(
    cx: &mut S,
    call: Func,
    callee: Rooted<StructRef>,
    argument: Option<[Val; 3]>,
) -> Result<Vec<Val>> {
    let context_value = field(cx, callee, F::FunctionContext)?;
    let context = structure(cx, context_value)?;
    let realm_value = field(cx, context, F::ContextRealm)?;
    let signature = call.ty(cx.as_context());
    let params: Vec<_> = signature.params().collect();
    require(
        params.len() == 10,
        "ABI6 R ProxyCall must append a nonnull calling P",
    )?;
    let owner_field = GcHostField::ContextDefiningProgram.definition();
    let owner_value = context.field(&mut *cx, owner_field.index() as usize)?;
    let owner = structure(cx, owner_value)?;
    let expected_owner = params[9].unwrap_ref();
    require(
        !expected_owner.is_nullable(),
        "calling P operand must be nonnull",
    )?;
    require(
        StructType::eq(
            &owner.ty(cx.as_context())?,
            expected_owner.heap_type().unwrap_concrete_struct(),
        ),
        "captured defining P does not match the actual ProxyCall ABI",
    )?;
    let array_ty = params[6]
        .unwrap_ref()
        .heap_type()
        .unwrap_concrete_array()
        .clone();
    let stored_ty = array_ty
        .element_type()
        .unwrap_val_type()
        .unwrap_ref()
        .heap_type()
        .unwrap_concrete_struct()
        .clone();
    let mut entries = Vec::new();
    if let Some(argument) = argument {
        require(stored_ty.fields().len() == 3, "StoredValue schema changed")?;
        let mut fields = vec![Val::I32(0); stored_ty.fields().len()];
        fields[F::StoredTag.index() as usize] = argument[0];
        fields[F::StoredScalar.index() as usize] = argument[1];
        fields[F::StoredRef.index() as usize] = argument[2];
        let pre = StructRefPre::new(&mut *cx, stored_ty);
        entries.push(Val::from(StructRef::new(&mut *cx, &pre, &fields)?));
    }
    let pre = ArrayRefPre::new(&mut *cx, array_ty);
    let argv = ArrayRef::new_fixed(&mut *cx, &pre, &entries)?;
    results(
        cx,
        call,
        &[
            Val::I32(Tag::Function.tag()),
            Val::I64(0),
            Val::from(callee),
            Val::I32(Tag::Undefined.tag()),
            Val::I64(0),
            Val::AnyRef(None),
            Val::from(argv),
            realm_value,
            Val::AnyRef(None),
            Val::from(owner),
        ],
    )
}

fn number(value: f64) -> [Val; 3] {
    [
        Val::I32(Tag::Number.tag()),
        Val::I64(value.to_bits() as i64),
        Val::AnyRef(None),
    ]
}

fn expect_return(value: &[Val], number: f64, stage: &str) -> Result<()> {
    // ProxyCall forwards the source body's Return. Normalization/restoration is
    // owned by its real Wasm Call caller; the host diagnostic does neither.
    require(
        value[0].unwrap_i32() == Tag::Number.tag()
            && value[1].unwrap_i64() == number.to_bits() as i64
            && matches!(value[2], Val::AnyRef(None))
            && i64::from(value[3].unwrap_i32()) == Kind::Return.abi_code()
            && value[4].unwrap_i32() == 0,
        &format!("NO-GO {stage}: expected Return({number}), got {value:?}"),
    )
}

fn enter_second<S: AsContextMut<Data = State>>(
    cx: &mut S,
    linker: &mut Linker<State>,
    fresh: &FreshRuntime,
    conflict: bool,
) -> Result<Rooted<StructRef>> {
    let artifact = emit(
        if conflict { P2_CONFLICT } else { P2 },
        conflict.then_some("return 23;"),
        fresh,
    )?;
    let module = validate_and_compile(cx.as_context().engine(), &artifact.bytes)?;
    link_hosts(cx, linker, &module)?;
    let instance = linker.instantiate(&mut *cx, &module)?;
    main_function(cx, instance)
}

fn nested(mut caller: Caller<'_, State>, inputs: &[Val], outputs: &mut [Val]) -> Result<()> {
    require(inputs.len() == 2 && outputs.is_empty(), "print ABI changed")?;
    let (mut linker, fresh, receive, retained_second, call, memory, case) = {
        let state = caller.data();
        require(!state.entered, "unexpected recursive print callback")?;
        (
            state
                .linker
                .clone()
                .ok_or_else(|| Error::msg("callback before arm"))?,
            Arc::clone(&state.fresh),
            state.receive.unwrap(),
            state.second,
            state.call.unwrap(),
            state.memory.unwrap(),
            state.case,
        )
    };
    let length = usize::try_from(inputs[1].unwrap_i32())?;
    require(
        length == b"compile-now".len(),
        "unexpected print trigger length",
    )?;
    let mut marker = vec![0; length];
    memory.read(
        &caller,
        usize::try_from(inputs[0].unwrap_i32())?,
        &mut marker,
    )?;
    require(marker == b"compile-now", "unexpected print trigger bytes")?;
    caller.data_mut().entered = true;

    let second = match case.order {
        EntryOrder::P1First => {
            require(
                retained_second.is_none(),
                "P2 entered before its scheduled callback",
            )?;
            let second = enter_second(&mut caller, &mut linker, &fresh, case.conflict)?;
            caller.data_mut().second = Some(second);
            second
        }
        EntryOrder::P2First => retained_second
            .ok_or_else(|| Error::msg("reverse-order P2 was not retained before P1 main"))?,
    };
    require(
        StructType::eq(&receive.ty(&caller)?, &second.ty(&caller)?),
        "independent P FunctionObject types did not canonicalize",
    )?;
    caller.gc(None)?;
    let value = invoke(
        &mut caller,
        call,
        receive,
        Some([
            Val::I32(Tag::Function.tag()),
            Val::I64(0),
            Val::from(second),
        ]),
    )?;
    expect_return(&value, 42.0, "forced-GC reentrant P2-to-P1 transport")?;
    caller.data_mut().transported = true;
    println!("reentrant-typed-GC-call=42 order={:?}", case.order);
    Ok(())
}

fn link_hosts<S: AsContextMut<Data = State>>(
    cx: &mut S,
    linker: &mut Linker<State>,
    module: &Module,
) -> Result<()> {
    for import in module.imports() {
        if import.module() == RUNTIME_IMPORT_NAMESPACE
            || linker.try_get_by_import(&mut *cx, &import)?.is_some()
        {
            continue;
        }
        match import.ty() {
            ExternType::Memory(ty) if ty.is_shared() => {
                let memory = SharedMemory::new(cx.as_context().engine(), ty)?;
                linker.define(&mut *cx, import.module(), import.name(), memory)?;
            }
            ExternType::Memory(ty) => {
                let memory = Memory::new(&mut *cx, ty)?;
                linker.define(&mut *cx, import.module(), import.name(), memory)?;
            }
            ExternType::Func(signature) => {
                let name = format!("{}::{}", import.module(), import.name());
                let byte_array = if name == "lila_host::byte_array_allocate" {
                    Some(
                        signature
                            .results()
                            .next()
                            .ok_or_else(|| Error::msg("missing byte-array result"))?
                            .unwrap_ref()
                            .heap_type()
                            .unwrap_concrete_array()
                            .clone(),
                    )
                } else {
                    None
                };
                linker.func_new(
                    import.module(),
                    import.name(),
                    signature,
                    move |mut caller, inputs, outputs| {
                        match name.as_str() {
                            "lila_host::print_line_utf8" => nested(caller, inputs, outputs),
                            "lila_host::collect_gc" => caller.gc(None),
                            "lila_host::compile_dynamic_function" => {
                                caller.data_mut().native_compile_attempts += 1;
                                Err(Error::msg(
                                    "prepared-only diagnostic reached native source compilation",
                                ))
                            }
                            "lila_host::weak_job_finish" => {
                                // Engine clears kept roots and resets its poll cursor here.
                                // This fresh diagnostic host permits no weak allocation,
                                // dereference or registry operation: all trap below, so
                                // its kept set and cursor remain empty/zero throughout.
                                require(
                                    inputs.is_empty() && outputs.is_empty(),
                                    "weak job finish ABI changed",
                                )
                            }
                            "lila_host::finalization_next_registry" => {
                                // The real host returns None when its registry vector
                                // is empty. Registry creation/registration traps here.
                                require(
                                    inputs.is_empty() && outputs.len() == 1,
                                    "finalization registry ABI changed",
                                )?;
                                outputs[0] = Val::AnyRef(None);
                                Ok(())
                            }
                            "lila_host::monotonic_clock_nanos" => {
                                require(
                                    inputs.is_empty() && outputs.len() == 1,
                                    "monotonic clock ABI changed",
                                )?;
                                let nanos = caller.data().monotonic_origin.elapsed().as_nanos();
                                outputs[0] = Val::I64(nanos.min(i64::MAX as u128) as i64);
                                Ok(())
                            }
                            "lila_host::agent_can_suspend" => {
                                outputs[0] = Val::I32(0);
                                Ok(())
                            }
                            "lila_host::byte_array_allocate" => {
                                let length = u32::try_from(inputs[0].unwrap_i32())?;
                                let pre = ArrayRefPre::new(
                                    &mut caller,
                                    byte_array.as_ref().unwrap().clone(),
                                );
                                outputs[0] =
                                    match ArrayRef::new(&mut caller, &pre, &Val::I32(0), length) {
                                        Ok(value) => Val::from(value),
                                        Err(error) if error.is::<GcHeapOutOfMemory<()>>() => {
                                            Val::AnyRef(None)
                                        }
                                        Err(error) => return Err(error),
                                    };
                                Ok(())
                            }
                            _ => Err(Error::msg(format!(
                                "unimplemented proof host callback executed: {name}"
                            ))),
                        }
                    },
                )?;
            }
            other => return Err(Error::msg(format!("unexpected proof import: {other:?}"))),
        }
    }
    Ok(())
}

fn run_case(engine: &Engine, r: &Module, fresh: &Arc<FreshRuntime>, case: Case) -> Result<()> {
    let artifact = emit(P1, Some("return 17;"), fresh)?;
    let p = validate_and_compile(engine, &artifact.bytes)?;
    let call_export = helper_export(fresh.runtime.bytes(), "helper::proxy_call")?;
    let mut store = Store::new(
        engine,
        State {
            limits: StoreLimitsBuilder::new()
                .memory_size(wasmtime_config::WASM_STORE_MEMORY_CAP_BYTES)
                .build(),
            monotonic_origin: std::time::Instant::now(),
            linker: None,
            fresh: Arc::clone(fresh),
            memory: None,
            receive: None,
            second: None,
            call: None,
            case,
            entered: false,
            transported: false,
            native_compile_attempts: 0,
        },
    );
    store.limiter(|state| &mut state.limits);
    store.set_epoch_deadline(u64::MAX / 2);
    let mut linker = Linker::new(engine);
    link_hosts(&mut store, &mut linker, r)?;
    let r_instance = linker.instantiate(&mut store, r)?;
    linker.instance(&mut store, RUNTIME_IMPORT_NAMESPACE, r_instance)?;
    let call = r_instance
        .get_func(&mut store, &call_export)
        .ok_or_else(|| Error::msg("missing actual R ProxyCall helper"))?;
    if matches!(case.order, EntryOrder::P2First) {
        let second = enter_second(&mut store, &mut linker, fresh, case.conflict)?;
        store.data_mut().second = Some(second);
        store.gc(None)?;
    }
    link_hosts(&mut store, &mut linker, &p)?;
    let p_instance = linker.instantiate(&mut store, &p)?;
    let receive = main_function(&mut store, p_instance)?;
    let before = invoke(&mut store, call, receive, Some(number(0.0)))?;
    expect_return(&before, 17.0, "baseline old P prepared Function hook")?;
    let memory = r_instance
        .get_memory(&mut store, "memory")
        .ok_or_else(|| Error::msg("missing R transient memory"))?;
    {
        let state = store.data_mut();
        state.linker = Some(linker);
        state.memory = Some(memory);
        state.receive = Some(receive);
        state.call = Some(call);
    }
    let outer = invoke(&mut store, call, receive, None)?;
    expect_return(&outer, 17.0, "old P resumed after reentrant callback")?;
    require(
        store.data().entered && store.data().transported,
        "host callback transport did not execute",
    )?;
    store.gc(None)?;
    let second = store
        .data()
        .second
        .ok_or_else(|| Error::msg("P2 function was not retained"))?;
    let retained = invoke(&mut store, call, second, Some(number(40.0)))?;
    expect_return(&retained, 42.0, "retained P2 after P1 and forced GC")?;
    let after = invoke(&mut store, call, receive, Some(number(0.0)))?;
    expect_return(
        &after,
        17.0,
        "old P prepared hook after P2 main and forced GC",
    )?;
    require(
        store.data().native_compile_attempts == 0,
        "prepared diagnostic must never invoke the native compiler callback",
    )?;
    println!(
        "case-passed conflict={} order={:?} outer=17 transport=42 old-P=17 native-misses=0",
        case.conflict, case.order
    );
    Ok(())
}

fn run(cases: Vec<Case>) -> Result<()> {
    let mode = wasmtime_config::WasmNativeCompilationMode::SizeOptimized;
    let mut config = wasmtime_config::base_config(mode, WasmBacktraceDetails::Disable);
    config.parallel_compilation(false);
    let engine = Engine::new(&config)?;
    wasmtime_policy::PRODUCT_WASMTIME_POLICY
        .verify_engine(&engine)
        .map_err(Error::msg)?;
    let fresh = Arc::new(FreshRuntime::build()?);
    // Compile these freshly emitted ABI6 R bytes once. No native deserialization,
    // old runtime package, shared R DSO or replacement JavaScript Engine exists.
    let r = validate_and_compile(&engine, fresh.runtime.bytes())?;
    for case in cases {
        run_case(&engine, &r, &fresh, case)?;
    }
    println!("prepared-only diagnostic completed; no native-miss/product/conformance claim");
    Ok(())
}

fn main() -> Result<()> {
    let mode = std::env::args().nth(1).unwrap_or_else(|| "all".to_owned());
    let conflicts: &[bool] = match mode.as_str() {
        "transport" => &[false],
        "conflict" => &[true],
        "all" => &[false, true],
        _ => return Err(Error::msg("usage: probe [transport|conflict|all]")),
    };
    let cases = conflicts
        .iter()
        .flat_map(|conflict| {
            [EntryOrder::P1First, EntryOrder::P2First].map(|order| Case {
                conflict: *conflict,
                order,
            })
        })
        .collect();
    std::thread::Builder::new()
        .stack_size(wasmtime_config::ENGINE_WORKER_STACK_SIZE)
        .spawn(move || run(cases))?
        .join()
        .map_err(|_| Error::msg("diagnostic worker panicked"))?
}
